window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6d46418f455220ec"]={"versions": [{"id": "FIG-6d46418f455220ec", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Schnittstellendiagramm im architektonischen Kontext der AUTOSAR Adaptive Platform (EXP_SWArchitecture). Das Diagramm spezifiziert die von dem Functional Cluster <em>Vehicle Update and Configuration Management</em> (VUCM) benötigten Schnittstellen (<em>required ports</em>) zu den Funktionsclustern <em>Time Synchronization</em> und <em>Persistency</em>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Functional Cluster und drei Port-Interfaces:</p>\n<ol class=\"fig-list\"><li><strong>Functional Cluster</strong>:\n<ul class=\"fig-list\"><li><code>«aapFunctionalCluster» Vehicle Update and Configuration Management</code> (daemon-based, oben dargestellt, orange hinterlegt).\n</li><li><code>«aapFunctionalCluster» Time Synchronization</code> (daemon-based, unten links dargestellt, blau hinterlegt).\n</li><li><code>«aapFunctionalCluster» Persistency</code> (unten rechts dargestellt, grün hinterlegt).\n</li></ul>\n</li><li><strong>Schnittstellen (<code>«aapAPI,aapPortInterface»</code>)</strong>:\n<ul class=\"fig-list\"><li><code>SynchronizedTimeBaseConsumer</code>: Bereitgestellt von <em>Time Synchronization</em> (Realisierungspfeil), genutzt von <em>Vehicle Update and Configuration Management</em> über einen Required Port (<code>«use» «aapRequiredPort»</code>). Methoden:\n<ul class=\"fig-list\"><li><code>+ GetCurrentTime()</code>\n</li><li><code>+ GetRateDeviation()</code>\n</li><li><code>+ GetTimeWithStatus(): SynchronizedTimeBaseStatus</code>\n</li><li><code>+ RegisterStatusChangeNotifier()</code>\n</li><li><code>+ RegisterSynchronizationStateChangeNotifier()</code>\n</li><li><code>+ RegisterTimeLeapNotifier()</code>\n</li><li><code>+ RegisterTimePrecisionMeasurementNotifier()</code>\n</li><li><code>+ RegisterTimeValidationNotification()</code>\n</li><li><code>+ UnregisterStatusChangeNotifier()</code>\n</li><li><code>+ UnregisterSynchronizationStateChangeNotifier()</code>\n</li><li><code>+ UnregisterTimeLeapNotifier()</code>\n</li><li><code>+ UnregisterTimePrecisionMeasurementNotifier()</code>\n</li><li><code>+ UnregisterTimeValidationNotification()</code>\n</li></ul>\n</li><li><code>FileStorage</code>: Bereitgestellt von <em>Persistency</em> (Realisierungspfeil), genutzt von <em>Vehicle Update and Configuration Management</em> über einen Required Port (<code>«use» «aapRequiredPort»</code>). Methoden:\n<ul class=\"fig-list\"><li><code>+ DeleteFile()</code>\n</li><li><code>+ FileExists()</code>\n</li><li><code>+ GetAllFileNames()</code>\n</li><li><code>+ GetCurrentFileSize()</code>\n</li><li><code>+ GetFileInfo()</code>\n</li><li><code>+ OpenFileReadOnly(): ReadAccessor</code>\n</li><li><code>+ OpenFileReadWrite(): ReadWriteAccessor</code>\n</li><li><code>+ OpenFileWriteOnly(): ReadWriteAccessor</code>\n</li><li><code>+ RecoverFile()</code>\n</li><li><code>+ ResetFile()</code>\n</li></ul>\n</li><li><code>KeyValueStorage</code>: Bereitgestellt von <em>Persistency</em> (Realisierungspfeil), genutzt von <em>Vehicle Update and Configuration Management</em> über einen Required Port (<code>«use» «aapRequiredPort»</code>). Methoden:\n<ul class=\"fig-list\"><li><code>+ DiscardPendingChanges()</code>\n</li><li><code>+ GetAllKeys()</code>\n</li><li><code>+ GetValue()</code>\n</li><li><code>+ KeyExists()</code>\n</li><li><code>+ RecoverKey()</code>\n</li><li><code>+ RemoveAllKeys()</code>\n</li><li><code>+ RemoveKey()</code>\n</li><li><code>+ ResetKey()</code>\n</li><li><code>+ SetValue()</code>\n</li><li><code>+ SyncToStorage()</code>\n</li></ul>\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Deklaration von Port-Interfaces und Abhängigkeiten; kein dynamischer Sequenzablauf im Diagramm dargestellt. Zur Laufzeit konsumiert der VUCM-Daemon Zeitsynchronisationsdienste (Abfrage synchronisierter Zeitbasen, Statusabfragen und Callback-Registrierungen für Zeitsprünge oder Genauigkeitsänderungen) sowie Persistenzdienste für strukturierte Schlüssel-Wert-Paare und dateibasierte Speicherung (Lesen, Schreiben, Wiederherstellen von Dateien).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition der C++-API- und Port-Interface-Signaturen für Applikations- und Cluster-Interaktionen auf der Adaptive Platform:</p>\n<ul class=\"fig-list\"><li>VUCM erfordert die Einbindung von Persistency (<code>FileStorage</code>, <code>KeyValueStorage</code>) und Time Synchronization (<code>SynchronizedTimeBaseConsumer</code>).\n</li><li>Persistency-Zugriff erfolgt über typisierte Accessor-Klassen (<code>ReadAccessor</code>, <code>ReadWriteAccessor</code>).\n</li><li>Benachrichtigungsmechanismen basieren auf expliziter Registrierung/Deregistrierung von Notifier-Callbacks für Status- und Zeitsprung-Ereignisse.\n</li></ul>"}, {"id": "FIG-b1176358c0c3e9cb", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Schnittstellendiagramm im architektonischen Kontext der AUTOSAR Adaptive Platform (EXP_SWArchitecture). Das Diagramm spezifiziert die von dem Functional Cluster <em>Vehicle Update and Configuration Management</em> (VUCM) benötigten Schnittstellen (<em>required ports</em>) zu den Funktionsclustern <em>Time Synchronization</em> und <em>Persistency</em>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Functional Cluster und drei Port-Interfaces:</p>\n<ol class=\"fig-list\"><li><strong>Functional Cluster</strong>:\n<ul class=\"fig-list\"><li><code>«aapFunctionalCluster» Vehicle Update and Configuration Management</code> (daemon-based, oben dargestellt, orange hinterlegt).\n</li><li><code>«aapFunctionalCluster» Time Synchronization</code> (daemon-based, unten links dargestellt, blau hinterlegt).\n</li><li><code>«aapFunctionalCluster» Persistency</code> (unten rechts dargestellt, grün hinterlegt).\n</li></ul>\n</li><li><strong>Schnittstellen (<code>«aapAPI,aapPortInterface»</code>)</strong>:\n<ul class=\"fig-list\"><li><code>SynchronizedTimeBaseConsumer</code>: Bereitgestellt von <em>Time Synchronization</em> (Realisierungspfeil), genutzt von <em>Vehicle Update and Configuration Management</em> über einen Required Port (<code>«use» «aapRequiredPort»</code>). Methoden:\n<ul class=\"fig-list\"><li><code>+ GetRateDeviation()</code>\n</li><li><code>+ GetTimeWithStatus(): SynchronizedTimeBaseStatus</code>\n</li><li><code>+ RegisterStatusChangeNotifier()</code>\n</li><li><code>+ RegisterSynchronizationStateChangeNotifier()</code>\n</li><li><code>+ RegisterTimeLeapNotifier()</code>\n</li><li><code>+ RegisterTimePrecisionMeasurementNotifier()</code>\n</li><li><code>+ RegisterTimeValidationNotification()</code>\n</li><li><code>+ UnregisterStatusChangeNotifier()</code>\n</li><li><code>+ UnregisterSynchronizationStateChangeNotifier()</code>\n</li><li><code>+ UnregisterTimeLeapNotifier()</code>\n</li><li><code>+ UnregisterTimePrecisionMeasurementNotifier()</code>\n</li><li><code>+ UnregisterTimeValidationNotification()</code>\n</li></ul>\n</li><li><code>FileStorage</code>: Bereitgestellt von <em>Persistency</em> (Realisierungspfeil), genutzt von <em>Vehicle Update and Configuration Management</em> über einen Required Port (<code>«use» «aapRequiredPort»</code>). Methoden:\n<ul class=\"fig-list\"><li><code>+ DeleteFile()</code>\n</li><li><code>+ FileExists()</code>\n</li><li><code>+ GetAllFileNames()</code>\n</li><li><code>+ GetCurrentFileSize()</code>\n</li><li><code>+ GetFileInfo()</code>\n</li><li><code>+ OpenFileReadOnly(): ReadAccessor</code>\n</li><li><code>+ OpenFileReadWrite(): ReadWriteAccessor</code>\n</li><li><code>+ OpenFileWriteOnly(): ReadWriteAccessor</code>\n</li><li><code>+ RecoverFile()</code>\n</li><li><code>+ ResetFile()</code>\n</li></ul>\n</li><li><code>KeyValueStorage</code>: Bereitgestellt von <em>Persistency</em> (Realisierungspfeil), genutzt von <em>Vehicle Update and Configuration Management</em> über einen Required Port (<code>«use» «aapRequiredPort»</code>). Methoden:\n<ul class=\"fig-list\"><li><code>+ DiscardPendingChanges()</code>\n</li><li><code>+ GetAllKeys()</code>\n</li><li><code>+ GetCurrentValueSize()</code>\n</li><li><code>+ GetValue()</code>\n</li><li><code>+ KeyExists()</code>\n</li><li><code>+ RecoverKey()</code>\n</li><li><code>+ RemoveAllKeys()</code>\n</li><li><code>+ RemoveKey()</code>\n</li><li><code>+ ResetKey()</code>\n</li><li><code>+ SetValue()</code>\n</li><li><code>+ SyncToStorage()</code>\n</li></ul>\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Deklaration von Port-Interfaces und Abhängigkeiten; kein dynamischer Sequenzablauf im Diagramm dargestellt. Zur Laufzeit konsumiert der VUCM-Daemon Zeitsynchronisationsdienste (Abfrage synchronisierter Zeitbasen, Statusabfragen und Callback-Registrierungen für Zeitsprünge oder Genauigkeitsänderungen) sowie Persistenzdienste für strukturierte Schlüssel-Wert-Paare und dateibasierte Speicherung (Lesen, Schreiben, Wiederherstellen von Dateien).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition der C++-API- und Port-Interface-Signaturen für Applikations- und Cluster-Interaktionen auf der Adaptive Platform:</p>\n<ul class=\"fig-list\"><li>VUCM erfordert die Einbindung von Persistency (<code>FileStorage</code>, <code>KeyValueStorage</code>) und Time Synchronization (<code>SynchronizedTimeBaseConsumer</code>).\n</li><li>Persistency-Zugriff erfolgt über typisierte Accessor-Klassen (<code>ReadAccessor</code>, <code>ReadWriteAccessor</code>).\n</li><li>Benachrichtigungsmechanismen basieren auf expliziter Registrierung/Deregistrierung von Notifier-Callbacks für Status- und Zeitsprung-Ereignisse.\n</li></ul>"}, {"id": "FIG-2c3c9fb4b691bf59", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Schnittstellendiagramm im architektonischen Kontext der AUTOSAR Adaptive Platform (EXP_SWArchitecture). Das Diagramm spezifiziert die von dem Functional Cluster <em>Vehicle Update and Configuration Management</em> (VUCM) benötigten Schnittstellen (<em>required ports</em>) zu den Funktionsclustern <em>Time Synchronization</em> und <em>Persistency</em>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Functional Cluster und drei Port-Interfaces:</p>\n<ol class=\"fig-list\"><li><strong>Functional Cluster</strong>:\n<ul class=\"fig-list\"><li><code>«aapFunctionalCluster» Vehicle Update and Configuration Management</code> (daemon-based, oben dargestellt, orange hinterlegt).\n</li><li><code>«aapFunctionalCluster» Time Synchronization</code> (daemon-based, unten links dargestellt, blau hinterlegt).\n</li><li><code>«aapFunctionalCluster» Persistency</code> (unten rechts dargestellt, grün hinterlegt).\n</li></ul>\n</li><li><strong>Schnittstellen (<code>«aapAPI,aapPortInterface»</code>)</strong>:\n<ul class=\"fig-list\"><li><code>SynchronizedTimeBaseConsumer</code>: Bereitgestellt von <em>Time Synchronization</em> (Realisierungspfeil), genutzt von <em>Vehicle Update and Configuration Management</em> über einen Required Port (<code>«use» «aapRequiredPort»</code>). Methoden:\n<ul class=\"fig-list\"><li><code>+ GetRateDeviation()</code>\n</li><li><code>+ GetTimeWithStatus(): SynchronizedTimeBaseStatus</code>\n</li><li><code>+ RegisterStatusChangeNotifier()</code>\n</li><li><code>+ RegisterSynchronizationStateChangeNotifier()</code>\n</li><li><code>+ RegisterTimeLeapNotifier()</code>\n</li><li><code>+ RegisterTimePrecisionMeasurementNotifier()</code>\n</li><li><code>+ RegisterTimeValidationNotification()</code>\n</li><li><code>+ UnregisterStatusChangeNotifier()</code>\n</li><li><code>+ UnregisterSynchronizationStateChangeNotifier()</code>\n</li><li><code>+ UnregisterTimeLeapNotifier()</code>\n</li><li><code>+ UnregisterTimePrecisionMeasurementNotifier()</code>\n</li><li><code>+ UnregisterTimeValidationNotification()</code>\n</li></ul>\n</li><li><code>FileStorage</code>: Bereitgestellt von <em>Persistency</em> (Realisierungspfeil), genutzt von <em>Vehicle Update and Configuration Management</em> über einen Required Port (<code>«use» «aapRequiredPort»</code>). Methoden:\n<ul class=\"fig-list\"><li><code>+ DeleteFile()</code>\n</li><li><code>+ FileExists()</code>\n</li><li><code>+ GetAllFileNames()</code>\n</li><li><code>+ GetCurrentFileSize()</code>\n</li><li><code>+ GetFileInfo()</code>\n</li><li><code>+ OpenFileReadOnly(): ReadAccessor</code>\n</li><li><code>+ OpenFileReadWrite(): ReadWriteAccessor</code>\n</li><li><code>+ OpenFileWriteOnly(): WriteAccessor</code>\n</li><li><code>+ RecoverFile()</code>\n</li><li><code>+ ResetFile()</code>\n</li></ul>\n</li><li><code>KeyValueStorage</code>: Bereitgestellt von <em>Persistency</em> (Realisierungspfeil), genutzt von <em>Vehicle Update and Configuration Management</em> über einen Required Port (<code>«use» «aapRequiredPort»</code>). Methoden:\n<ul class=\"fig-list\"><li><code>+ DiscardPendingChanges()</code>\n</li><li><code>+ GetAllKeys()</code>\n</li><li><code>+ GetCurrentValueSize()</code>\n</li><li><code>+ GetValue()</code>\n</li><li><code>+ KeyExists()</code>\n</li><li><code>+ RecoverKey()</code>\n</li><li><code>+ RemoveAllKeys()</code>\n</li><li><code>+ RemoveKey()</code>\n</li><li><code>+ ResetKey()</code>\n</li><li><code>+ SetValue()</code>\n</li><li><code>+ SyncToStorage()</code>\n</li></ul>\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Deklaration von Port-Interfaces und Abhängigkeiten; kein dynamischer Sequenzablauf im Diagramm dargestellt. Zur Laufzeit konsumiert der VUCM-Daemon Zeitsynchronisationsdienste (Abfrage synchronisierter Zeitbasen, Statusabfragen und Callback-Registrierungen für Zeitsprünge oder Genauigkeitsänderungen) sowie Persistenzdienste für strukturierte Schlüssel-Wert-Paare und dateibasierte Speicherung (Lesen, Schreiben, Wiederherstellen von Dateien).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition der C++-API- und Port-Interface-Signaturen für Applikations- und Cluster-Interaktionen auf der Adaptive Platform:</p>\n<ul class=\"fig-list\"><li>VUCM erfordert die Einbindung von Persistency (<code>FileStorage</code>, <code>KeyValueStorage</code>) und Time Synchronization (<code>SynchronizedTimeBaseConsumer</code>).\n</li><li>Persistency-Zugriff erfolgt über typisierte Accessor-Klassen (<code>ReadAccessor</code>, <code>ReadWriteAccessor</code>, <code>WriteAccessor</code>), wobei <code>OpenFileWriteOnly()</code> strikt auf <code>WriteAccessor</code> typisiert ist.\n</li><li>Benachrichtigungsmechanismen basieren auf expliziter Registrierung/Deregistrierung von Notifier-Callbacks für Status- und Zeitsprung-Ereignisse.\n</li></ul>"}], "trans": [{"from": "FIG-6d46418f455220ec", "to": "FIG-b1176358c0c3e9cb", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>In <code>SynchronizedTimeBaseConsumer</code> (<code>Time Synchronization</code>) entfällt die Methode <code>+ GetCurrentTime()</code>.\n</li><li>In <code>KeyValueStorage</code> (<code>Persistency</code>) wird die Methode <code>+ GetCurrentValueSize()</code> ergänzt.\n</li><li>Keine sonstigen Änderungen an Schnittstellenbeziehungen oder Cluster-Definitionen.\n</li></ul>"}, {"from": "FIG-b1176358c0c3e9cb", "to": "FIG-2c3c9fb4b691bf59", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>In <code>FileStorage</code> (<code>Persistency</code>) ändert sich der Rückgabetyp der Operation <code>+ OpenFileWriteOnly()</code> von <code>ReadWriteAccessor</code> zu <code>WriteAccessor</code>.\n</li></ul>"}]};
